import{z as n,x as o,o as B,c as C,q as e,j as r,D as a,d as l,s as i,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"多轮对话合成","description":"","frontmatter":{"title":"多轮对话合成","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-multiturn.md","filePath":"llm/synthetic-multiturn.md","lastUpdated":1791413859000}'),d={name:"llm/synthetic-multiturn.md"};function p(m,E,D,F,h,u){const t=o("Mermaid");return B(),C("div",null,[E[2]||(E[2]=e('<h1 id="多轮对话合成" tabindex="-1">多轮对话合成 <a class="header-anchor" href="#多轮对话合成" aria-label="Permalink to &quot;多轮对话合成&quot;">​</a></h1><div class="epigraph"><p>对话合成的核心设计不是让两个模型说话，是让它们知道的不一样：信息不对称立住了，多轮才有信息量。</p><footer>—— 据 Li 等 CAMEL；Ding 等 UltraChat 整理</footer></div><p><a href="/llm/synthetic-code-pipeline">上一课</a>的代码域靠执行把真值钉死；对话域没有程序真值，验证从「判对错」退到「判连贯、一致与目标达成」，质量控制的重心随之后移——从过滤器移到生成结构的设计。本课写多轮对话的三种生成结构，以及它们各自在何处最常崩。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多轮数据的合成难点不是生成单轮回复——那是教师的老本行——而是制造「有内容的轮次推进」。三种结构的缺口不同。角色扮演双模型：给两个模型各设角色自由互聊，便宜且长，但会崩向两种吸收态：无限客套（双方礼貌互捧不推进任务）与角色漂移（几轮后用户开始替助手答）。用户模拟器结构：一个模型持隐藏目标扮用户，另一个扮助手，轮次推进由目标驱动，目标达成度可以程序化判定——这是对话域里少有的准真值，但它的质量完全押在模拟器的纪律上。单模型自问自答：教师一个人写整段对话，最便宜，但轮间相关性极强，深轮次基本是首轮的复述。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>结构选型按任务定。任务导向对话（订票、排查、表单填写）用用户模拟器：目标与约束写进模拟器侧的系统提示，助手不可见；任务完成判定用状态检查——槽位填齐、条件确认——这给了过滤一个程序抓手。开放域对话用角色扮演加崩溃检测：角色卡要带「禁止替对方说话」与轮次职责边界，检测器盯三类崩坏——角色漂移、任务遗忘、复读循环——命中即截断重 roll，不让坏轨迹流进整形。自问自答只当增广：多轮损失只打助手轮（<a href="/llm/multiturn-loss-mask">多轮 loss mask</a>课的规矩），用户轮文本质量的影响本就低，但对话级通顺仍要人审抽样。</p><p>轮次深度是配比维度：合成对话普遍停在三四轮，因为每深一轮，模拟器要同时记住的活跃约束和槽位继续累积。深轮次要专门造——长任务、多约束、中途改需求三类模板——并单独配比，否则训练出的模型见长对话就崩。<span class="marginnote">深一轮贵多少可以直接数：一轮要守 1 条约束，三四轮对话模拟器得同时记住 3-4 个槽位加历史承诺，到六轮以上约束数翻倍、崩坏率随之上升——这就是合成对话普遍停在三四轮的算术原因。</span></p>',8)),(B(),r(s,null,{default:a(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E7%9B%AE%E6%A0%87%E4%B8%8E%E7%BA%A6%E6%9D%9F%EF%BC%9A%E4%BB%85%E6%A8%A1%E6%8B%9F%E5%99%A8%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20SIM%5B%22%E7%94%A8%E6%88%B7%E6%A8%A1%E6%8B%9F%E5%99%A8%22%5D%0A%20%20SIM%20--%3E%20UTTER%5B%22%E7%94%A8%E6%88%B7%E8%BD%AE%22%5D%0A%20%20UTTER%20--%3E%20ASST%5B%22%E5%8A%A9%E6%89%8B%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20ASST%20--%3E%20REPLY%5B%22%E5%8A%A9%E6%89%8B%E8%BD%AE%22%5D%0A%20%20REPLY%20--%3E%20STATE%7B%22%E7%8A%B6%E6%80%81%E6%A3%80%E6%9F%A5%EF%BC%9A%E6%A7%BD%E4%BD%8D%E4%B8%8E%E6%9D%A1%E4%BB%B6%22%7D%0A%20%20STATE%20--%3E%7C%E6%9C%AA%E8%BE%BE%E6%88%90%E4%B8%94%E6%9C%AA%E5%B4%A9%E5%9D%8F%7C%20SIM%0A%20%20STATE%20--%3E%7C%E8%BE%BE%E6%88%90%7C%20OK%5B%22%E8%BD%A8%E8%BF%B9%E5%85%A5%E5%BA%93%EF%BC%9A%E5%B8%A6%E5%AE%8C%E6%88%90%E6%A0%87%E8%AE%B0%22%5D%0A%20%20STATE%20--%3E%7C%E8%A7%92%E8%89%B2%E6%BC%82%E7%A7%BB%E6%88%96%E5%A4%8D%E8%AF%BB%7C%20REROLL%5B%22%E6%88%AA%E6%96%AD%E9%87%8D%20roll%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[l("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"信息不对称是机制核心：模拟器知道目标而助手不知道，对话的信息量来自助手从「不知道」走到「知道」的过程。泄漏摧毁这个机制——目标一旦出现在助手可见上下文里（模板拼接错误、多轮改写时带入），对话就退化成朗读，完成率虚高。崩溃检测的存在理由是吸收态不是随机噪声而是吸引子：客套互捧对双方都是低风险高流利的续写方向，采样天然滑进去；检测器按崩坏类型分类统计，哪类吸收态占比上升，就补哪个方向的算子或角色卡约束。模拟器与助手同源的风险与代码域的自食同构：同一教师既出题又答题，题会越来越像它能答的样子；缓解照旧——生成与判定分离，模拟器与助手至少用不同版本或不同温度段。",-1)),E[5]||(E[5]=A("p",null,[A("span",{class:"marginnote"},"多轮合成的常见事故不是答错，是「用户帮忙」：模拟器把约束和目标全替助手说了，完成率满分但对话无信息量。审计指标不是完成率，是助手轮的信息增量——目标信息首次由助手自己问出来才算数。")],-1)),(B(),r(s,null,{default:a(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E9%9A%90%E8%97%8F%E7%9B%AE%E6%A0%87%EF%BC%9A%E8%AE%A2%E4%B8%80%E5%BC%A0%E5%8C%97%E4%BA%AC%E5%88%B0%E4%B8%8A%E6%B5%B7%E7%9A%84%E6%9C%BA%E7%A5%A8%22%5D%20--%3E%20CHK%7B%22%E7%9B%AE%E6%A0%87%E6%98%AF%E5%90%A6%E5%87%BA%E7%8E%B0%E5%9C%A8%E5%8A%A9%E6%89%8B%E5%8F%AF%E8%A7%81%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%EF%BC%8C%E6%B3%84%E6%BC%8F%E8%A2%AB%E6%8C%A1%E4%BD%8F%7C%20ASK%5B%22%E5%8A%A9%E6%89%8B%E5%8F%AA%E8%83%BD%E4%BB%8E%E7%94%A8%E6%88%B7%E8%BD%AE%E9%87%8C%E4%B8%80%E7%82%B9%E7%82%B9%E9%97%AE%22%5D%0A%20%20ASK%20--%3E%20INC%5B%22%E4%BF%A1%E6%81%AF%E5%A2%9E%E9%87%8F%E7%9C%9F%E5%AE%9E%EF%BC%9A%E8%BD%A8%E8%BF%B9%E5%85%A5%E5%BA%93%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%EF%BC%8C%E6%8B%BC%E6%8E%A5%E9%94%99%E8%AF%AF%E5%B8%A6%E5%85%A5%7C%20READ%5B%22%E5%8A%A9%E6%89%8B%E7%9B%B4%E6%8E%A5%E7%85%A7%E7%9D%80%E7%9B%AE%E6%A0%87%E6%9C%97%E8%AF%BB%22%5D%0A%20%20READ%20--%3E%20FAKE%5B%22%E5%AE%8C%E6%88%90%E7%8E%87%E6%BB%A1%E5%88%86%E4%BD%86%E9%9B%B6%E4%BF%A1%E6%81%AF%E9%87%8F%EF%BC%9A%E6%95%B4%E6%AE%B5%E4%B8%A2%E5%BC%83%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=e('<p><span class="marginnote">信息不对称可以类比猜谜：出谜的人知道答案，猜的人才觉得有趣。模拟器持目标扮用户，助手必须靠提问把信息问出来；一旦谜底提前贴在墙上（目标泄漏），「猜谜」就退化成「念谜底」，这段对话对训练毫无价值。</span></p><p><span class="marginnote">吸收态、吸引子是动力系统术语，意思是演化到某个状态后就出不来了。对话里「好的谢谢」「请再说一遍」式客套互捧就是这样的状态——对语言模型是低风险高流利的续写方向，采样天然滑进去，所以要按崩坏类型检测、命中即截断重 roll。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无程序真值的部分（开放闲聊的情感推进、风格一致性）只能裁判打分加人审，拦截率回到谱系里最弱的一档。模拟器的语言与人群偏置直接写进数据：它会用同一种口吻「当用户」，用户侧多样性要靠角色卡与语料种子显式撑开。长对话的上下文成本随轮次增长，深轮次合成的算力预算要单独列。最后，对话合成与偏好数据的分工不同：这里造的是「对话怎么进行」，偏好对造的是「哪种回复更好」，两者的数据形状与训练目标都不同，不要用一套管线硬融。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三种结构：用户模拟器持隐藏目标、角色扮演加崩溃检测、自问自答只当增广。</li><li>信息不对称是多轮信息量的来源，目标泄漏让对话退化成朗读。</li><li>吸收态是吸引子：客套互捧与复读要按类型检测、截断重 roll。</li><li>轮次深度是配比维度，深轮次要专门造。</li><li>审计看助手轮的信息增量，不看完成率。</li><li>出处：Li 等 CAMEL 2023；Ding 等 UltraChat 2023；loss mask 规矩见本站专课。</li></ul>',6))])}const f=n(d,[["render",p]]);export{c as __pageData,f as default};
